import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"VFS and the filesystem family","description":"","frontmatter":{},"headers":[],"relativePath":"arch/vfs.md","filePath":"arch/vfs.md"}'),r={name:"arch/vfs.md"};function i(c,e,n,f,d,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="vfs-and-the-filesystem-family" tabindex="-1">VFS and the filesystem family <a class="header-anchor" href="#vfs-and-the-filesystem-family" aria-label="Permalink to &quot;VFS and the filesystem family&quot;">​</a></h1><h2 id="the-vfs-contract" tabindex="-1">The VFS contract <a class="header-anchor" href="#the-vfs-contract" aria-label="Permalink to &quot;The VFS contract&quot;">​</a></h2><p><code>fs/fs_vfs.{c,h}</code>: one API - open/read/write/seek/close/stat/mkdir/ rmdir/readdir/lookup - over registered filesystem types. A type registers mount/unmount hooks plus file_ops and dir_ops. The global node tree resolves paths and crosses mount points transparently.</p><p>Real behaviours: per-fs case sensitivity in the node cache, enforced permission bits (mode 0000 refuses), bitwise write-access checks, i64 seek, <code>umount /</code> refused, mount shadowing without duplicate children, bounded <code>list_mounts</code>.</p><h2 id="fat32-fs-fs-fat32-c" tabindex="-1">FAT32 (<code>fs/fs_fat32.c</code>) <a class="header-anchor" href="#fat32-fs-fs-fat32-c" aria-label="Permalink to &quot;FAT32 (`fs/fs_fat32.c`)&quot;">​</a></h2><p>LFN with alias generation + collision scan; checksum and sequence validation on read; cross-cluster LFN deletion with backtrack; dual- FAT mirror maintained; FSINFO read + maintained + persisted with the next-free hint.</p><h2 id="exfat-fs-fs-exfat-c" tabindex="-1">exFAT (<code>fs/fs_exfat.c</code>) <a class="header-anchor" href="#exfat-fs-fs-exfat-c" aria-label="Permalink to &quot;exFAT (`fs/fs_exfat.c`)&quot;">​</a></h2><p>Active-FAT tracking, upcase table handling, cluster chains.</p><h2 id="ext4-fs-fs-ext4-c" tabindex="-1">ext4 (<code>fs/fs_ext4.c</code>) <a class="header-anchor" href="#ext4-fs-fs-ext4-c" aria-label="Permalink to &quot;ext4 (`fs/fs_ext4.c`)&quot;">​</a></h2><p>Extent-based reads and writes, block groups, inode tables.</p><h2 id="ramfs-fs-fs-ramfs-c" tabindex="-1">ramfs (<code>fs/fs_ramfs.c</code>) <a class="header-anchor" href="#ramfs-fs-fs-ramfs-c" aria-label="Permalink to &quot;ramfs (`fs/fs_ramfs.c`)&quot;">​</a></h2><p>The volatile root filesystem; sparse holes read back as zeros.</p><h2 id="the-etc-volume" tabindex="-1">The /etc volume <a class="header-anchor" href="#the-etc-volume" aria-label="Permalink to &quot;The /etc volume&quot;">​</a></h2><p>A 32 MiB FAT32 image mounted at /etc (config, SSH keys, logs, crash dumps) - built by the Makefile from <code>etc/opencube.conf</code>. It is the persistence story for an otherwise in-memory system.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p><code>fstest</code> (the dual-sided assertion suite), <code>fsck</code>, <code>fatstat</code>, <code>fs_mount_test</code>, plus the host-side harnesses in <code>tests/</code> (FAT structure parsing with ASAN). The regression battery runs fstest on every boot.</p>',16)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
